    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ファクター', 'ファクター', 'hệ số chuẩn hóa nồng độ; 力価', '', '', '', 12);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ランプ', 'ランプ', 'đèn; trong đề là đèn nguồn sáng', '', '', '', 13);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ガスクロマトグラフ', 'ガスクロマトグラフ', 'máy sắc ký khí', '', '', '', 14);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'キレート', 'キレート', 'chelat; phức có vòng tạo bởi phối tử nhiều càng', '', '', '', 15);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'サンプリング', 'サンプリング', 'lấy mẫu', '', '', '', 16);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'アンモニア', 'アンモニア', 'amoniac, NH₃', '', '', '', 17);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'フェノールフタレイン', 'フェノールフタレイン', 'phenolphthalein; chỉ thị axit–bazơ', '', '', '', 18);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ジフェニルカルバジド', 'ジフェニルカルバジド', 'diphenylcarbazide; thuốc thử tạo màu với Cr(VI)', '', '', '', 19);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'アセトン', 'アセトン', 'axeton; CH₃COCH₃', '', '', '', 20);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'エタノール', 'エタノール', 'etanol; C₂H₅OH', '', '', '', 21);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'アルケン／アルキン', 'アルケン／アルキン', 'anken / ankin; phân biệt liên kết đôi / ba', '', '', '', 22);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'フェノール／アニリン', 'フェノール／アニリン', 'phenol / anilin; axit yếu / bazơ yếu', '', '', '', 23);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'オゾン', 'オゾン', 'ozon; O₃', '', '', '', 24);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'アルカリ', 'アルカリ', 'kiềm', '', '', '', 25);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ボンベ', 'ボンベ', 'bình chứa khí áp suất cao', '', '', '', 26);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'テトラアンミン', 'テトラアンミン', 'tetraammin; bốn phối tử NH₃', '', '', '', 27);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', 'Mẫu câu tiếng Nhật', 'Cách đọc bằng kana', 'Nghĩa tiếng Việt / cách xử lý khi làm bài', '', '', '', 28);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～は、～である。', '～は、～である。', '“... là ...”. Kiểm tra toàn bộ định nghĩa và điều kiện.', '', '', '', 29);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～してはならない。', '～してはならない。', '“Không được ...”. Đây là điều cấm, không phải lời khuyên.', '', '', '', 30);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～しなければならない。', '～しなければならない。', '“Phải ...”. Kiểm tra hành động có thật sự bắt buộc không.', '', '', '', 31);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～してもよい。', '～してもよい。', '“Có thể / được phép ...”. Chú ý điều kiện cho phép và an toàn.', '', '', '', 32);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～を用いると、～できる。', '～をもちいると、～できる。', '“Dùng ... thì có thể ...”. Xét quan hệ nguyên nhân và kết quả.', '', '', '', 33);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～を加えると、～が生じる。', '～をくわえると、～がしょうじる。', '“Thêm ... thì xuất hiện ...”. Kiểm tra lượng thuốc thử và hiện tượng.', '', '', '', 34);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～を過剰に加えると、～。', '～をかじょうにくわえると、～。', '“Khi thêm dư ...”. Phân biệt với lượng ít; có thể tạo phức tan.', '', '', '', 35);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～よりも、～。', '～よりも、～。', '“... hơn ...”. Không đảo chiều so sánh.', '', '', '', 36);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～の場合、～。', '～のばあい、～。', '“Trong trường hợp ...”. Điều kiện giới hạn phạm vi kết luận.', '', '', '', 37);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '一般に、～。', 'いっぱんに、～。', '“Nhìn chung ...”. Không tự biến thành quy luật tuyệt đối.', '', '', '', 38);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', 'いずれも～。', 'いずれも～。', '“Tất cả đều ...”. Chỉ một trường hợp không đúng cũng bác bỏ phát biểu.', '', '', '', 39);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～以下／～以上', '～いか／～いじょう', '“Không quá / ít nhất ...”. Cả hai đều gồm giá trị ở ranh giới.', '', '', '', 40);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～に比例する。', '～にひれいする。', '“Tỉ lệ thuận với ...”. Phân biệt 反比例（はんぴれい）: tỉ lệ nghịch.', '', '', '', 41);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～とすれば、～。', '～とすれば、～。', '“Nếu đặt / giả sử ...”. Giữ nguyên tên biến, đơn vị và giả thiết.', '', '', '', 42);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～に留意すれば、～。', '～にりゅういすれば、～。', '“Nếu chú ý đến ...”. Trong phép tính, xét chữ số có nghĩa trước khi làm tròn.', '', '', '', 43);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～が共存する／共存下', '～がきょうぞんする／きょうぞんか', '“Có mặt đồng thời / trong sự hiện diện của ...”. Xét môi trường phản ứng.', '', '', '', 44);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～のもとで、～。', '～のもとで、～。', '“Trong điều kiện ...”. Kiểm tra nhiệt độ, áp suất và lượng chất được giữ cố định.', '', '', '', 45);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～とは、～をいう。', '～とは、～をいう。', '“... được định nghĩa là ...”. So sánh đúng khái niệm, không chỉ từ khóa.', '', '', '', 46);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 1, '白金るつぼは、王水で洗浄するのがよい。', 'Nên rửa chén nung bằng platin bằng nước cường toan.', NULL, '×', 'Nước cường toan hòa tan platin, vì vậy sẽ ăn mòn chén nung. Chọn quy trình làm sạch tương thích với vật liệu và chất bẩn; không dùng nước cường toan cho chén platin. Điểm dễ nhầm: platin bền với nhiều axit riêng lẻ nhưng không bền với hỗn hợp axit có tính oxi hóa và tạo phức này.', '[{"term": "白金", "reading": "はっきん", "meaning": "platin"}, {"term": "るつぼ", "reading": "るつぼ", "meaning": "chén nung"}, {"term": "王水", "reading": "おうすい", "meaning": "nước cường toan"}, {"term": "洗浄", "reading": "せんじょう", "meaning": "rửa, làm sạch"}]'::jsonb, 1);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 2, 'メスフラスコは、加熱して乾燥させてはならない。', 'Không được làm khô bình định mức bằng cách gia nhiệt.', NULL, '○', 'Bình định mức là dụng cụ đo thể tích được hiệu chuẩn ở nhiệt độ quy định. Gia nhiệt mạnh có thể ảnh hưởng đến hình dạng và độ chính xác, nên để ráo hoặc làm khô theo quy trình phù hợp. Khi pha dung dịch nước, bình còn một ít nước tinh khiết không làm đổi lượng chất tan nếu cuối cùng định mức đúng vạch.', '[{"term": "メスフラスコ", "reading": "メスフラスコ", "meaning": "bình định mức"}, {"term": "加熱", "reading": "かねつ", "meaning": "gia nhiệt"}, {"term": "乾燥", "reading": "かんそう", "meaning": "làm khô"}, {"term": "標線", "reading": "ひょうせん", "meaning": "vạch định mức"}]'::jsonb, 2);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 3, '紫外可視分光光度計の光源には、一般に、中空陰極ランプが用いられる。', 'Trong máy quang phổ hấp thụ tử ngoại–khả kiến, nguồn sáng thường được dùng là đèn catốt rỗng.', NULL, '×', 'Máy UV–Vis thường dùng nguồn phổ liên tục: đèn deuteri ở vùng tử ngoại và đèn tungsten/halogen ở vùng khả kiến; một số máy dùng xenon. Đèn catốt rỗng cho các vạch đặc trưng của nguyên tố và thường dùng trong hấp thụ nguyên tử. Điểm dễ nhầm là tên hai phương pháp quang phổ.', '[{"term": "紫外可視分光光度計", "reading": "しがいかしぶんこうこうどけい", "meaning": "máy quang phổ UV–Vis"}, {"term": "光源", "reading": "こうげん", "meaning": "nguồn sáng"}, {"term": "中空陰極ランプ", "reading": "ちゅうくういんきょくランプ", "meaning": "đèn catốt rỗng"}, {"term": "重水素", "reading": "じゅうすいそ", "meaning": "deuteri"}]'::jsonb, 3);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 4, '減圧蒸留を用いると、低い温度で蒸留することができる。', 'Khi dùng chưng cất giảm áp, có thể chưng cất ở nhiệt độ thấp.', NULL, '○', 'Chất lỏng sôi khi áp suất hơi bằng áp suất bên ngoài. Giảm áp suất bên ngoài làm giảm nhiệt độ sôi, nên có thể chưng cất ở nhiệt độ thấp hơn so với áp suất thường. Phương pháp hữu ích với chất có nhiệt độ sôi cao hoặc dễ phân hủy do nhiệt; không nhầm giảm áp với tăng áp.', '[{"term": "減圧蒸留", "reading": "げんあつじょうりゅう", "meaning": "chưng cất giảm áp"}, {"term": "温度", "reading": "おんど", "meaning": "nhiệt độ"}, {"term": "沸点", "reading": "ふってん", "meaning": "nhiệt độ sôi"}, {"term": "蒸気圧", "reading": "じょうきあつ", "meaning": "áp suất hơi"}]'::jsonb, 4);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 5, '炭酸ナトリウム(Na₂CO₃)標準溶液を調製する場合、誤差を少なくするため、精秤した炭酸ナトリウムの粉末を直接、メスフラスコに入れ、よく溶かした後、標線まで希釈する。', 'Khi pha dung dịch chuẩn natri cacbonat (Na₂CO₃), để giảm sai số, cho trực tiếp bột natri cacbonat đã cân chính xác vào bình định mức, hòa tan kỹ rồi pha loãng đến vạch định mức.', NULL, '×', 'Quy trình phù hợp là hòa tan chất đã cân trong cốc với nước, chuyển định lượng sang bình định mức, rửa cốc và dụng cụ chuyển nhiều lần rồi gộp nước rửa. Để về nhiệt độ hiệu chuẩn trước khi thêm nước tới vạch. Cho bột trực tiếp dễ làm chất bám ở cổ bình, khó hòa tan hoặc chuyển hết; không thể xem đó là biện pháp giảm sai số.', '[{"term": "炭酸ナトリウム", "reading": "たんさんナトリウム", "meaning": "natri cacbonat"}, {"term": "標準溶液", "reading": "ひょうじゅんようえき", "meaning": "dung dịch chuẩn"}, {"term": "精秤", "reading": "せいひょう", "meaning": "cân chính xác"}, {"term": "希釈", "reading": "きしゃく", "meaning": "pha loãng"}]'::jsonb, 5);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 6, '1.0 mol/Lの水酸化ナトリウム溶液250 mLを調製するには、水酸化ナトリウム(NaOH 式量40.0)10 gを、水250 mLに溶解させればよい。', 'Để pha 250 mL dung dịch natri hiđroxit 1.0 mol/L, chỉ cần hòa tan 10 g natri hiđroxit (NaOH, khối lượng công thức 40.0) vào 250 mL nước.', NULL, '×', 'Khối lượng tính theo lý thuyết đúng: n = 1.0 × 0.250 = 0.25 mol; m = 0.25 × 40.0 = 10 g. Sai ở thể tích: 250 mL là thể tích dung dịch cuối cùng, không phải thể tích nước ban đầu. Hòa tan trong lượng nước nhỏ hơn, để nguội rồi định mức đến 250 mL. NaOH hút ẩm và hấp thụ CO₂, nên dung dịch dùng chính xác còn cần được chuẩn hóa.', '[{"term": "水酸化ナトリウム", "reading": "すいさんかナトリウム", "meaning": "natri hiđroxit"}, {"term": "式量", "reading": "しきりょう", "meaning": "khối lượng công thức"}, {"term": "溶解", "reading": "ようかい", "meaning": "hòa tan"}, {"term": "調製", "reading": "ちょうせい", "meaning": "pha chế"}]'::jsonb, 6);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 7, '標準液の濃度を表示濃度どおりに調製することは困難であるため、一般に、表示濃度に近い程度に調製し、ファクター(力価)を決めておく。', 'Vì khó pha dung dịch chuẩn có nồng độ đúng tuyệt đối bằng nồng độ ghi trên nhãn, thông thường người ta pha gần nồng độ ghi trên nhãn rồi xác định hệ số (hệ số chuẩn hóa).', NULL, '○', 'Chuẩn hóa xác định nồng độ thực của dung dịch. Với f = c thực/c ghi nhãn, khi tính lượng chất phải dùng c thực = f × c ghi nhãn. Điểm dễ nhầm: dung dịch được pha gần đúng vẫn dùng để định lượng chính xác được nếu hệ số đã được xác định đúng và dung dịch còn ổn định.', '[{"term": "表示濃度", "reading": "ひょうじのうど", "meaning": "nồng độ ghi nhãn"}, {"term": "ファクター", "reading": "ファクター", "meaning": "hệ số chuẩn hóa"}, {"term": "力価", "reading": "りきか", "meaning": "hệ số chuẩn hóa"}, {"term": "標定", "reading": "ひょうてい", "meaning": "chuẩn hóa dung dịch"}]'::jsonb, 7);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 8, '水溶液を取り扱う場合、全量ピペット(ホールピペット)は、乾いた状態で使用しなければならない。', 'Khi thao tác với dung dịch nước, pipet bầu (pipet toàn phần) bắt buộc phải được sử dụng ở trạng thái khô.', NULL, '×', 'Không bắt buộc làm khô. Sau khi rửa, tráng pipet bằng một lượng nhỏ chính dung dịch cần lấy để loại nước còn sót, rồi hút mẫu. Nước còn trong pipet chưa được tráng có thể pha loãng mẫu. Phân biệt pipet lấy một thể tích dung dịch có nồng độ xác định với bình định mức pha đến thể tích cuối.', '[{"term": "全量ピペット", "reading": "ぜんりょうピペット", "meaning": "pipet bầu"}, {"term": "ホールピペット", "reading": "ホールピペット", "meaning": "pipet toàn phần"}, {"term": "水溶液", "reading": "すいようえき", "meaning": "dung dịch nước"}, {"term": "共洗い", "reading": "ともあらい", "meaning": "tráng bằng dung dịch sẽ dùng"}]'::jsonb, 8);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 9, 'ジフェニルカルバジドは、弱酸性でクロム(III)と反応して赤紫色を呈する。', 'Trong môi trường axit yếu, diphenylcarbazide phản ứng với crom(III) và tạo màu đỏ tím.', NULL, '×', 'Thuốc thử diphenylcarbazide được dùng để nhận biết hoặc định lượng Cr(VI) trong môi trường axit. Trong phản ứng tạo màu, Cr(VI) bị khử và thuốc thử bị oxi hóa; phức có màu liên quan đến Cr(III) hình thành sau phản ứng. Không vì phức cuối chứa Cr(III) mà kết luận thuốc thử phản ứng trực tiếp với Cr(III) như câu nêu.', '[{"term": "ジフェニルカルバジド", "reading": "ジフェニルカルバジド", "meaning": "diphenylcarbazide"}, {"term": "弱酸性", "reading": "じゃくさんせい", "meaning": "tính axit yếu"}, {"term": "クロム", "reading": "クロム", "meaning": "crom"}, {"term": "赤紫色", "reading": "せきししょく", "meaning": "màu đỏ tím"}]'::jsonb, 9);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 10, 'Cu²⁺を含む水溶液に適量のアンモニア水を加えると、淡青色の水酸化銅(II)が沈殿するが、この沈殿は、アンモニア水を過剰に加えると再び溶解する。', 'Khi thêm lượng thích hợp nước amoniac vào dung dịch nước chứa Cu²⁺, hiđroxit đồng(II) màu xanh nhạt kết tủa; nhưng kết tủa này hòa tan trở lại khi thêm dư nước amoniac.', NULL, '○', 'Lúc đầu NH₃ tạo OH⁻ trong nước, làm xuất hiện Cu(OH)₂ màu xanh nhạt. Khi NH₃ dư, ion đồng tạo phức ammin tan màu xanh đậm, thường biểu diễn [Cu(NH₃)₄]²⁺. Điểm dễ nhầm là kết tủa xanh nhạt khác với dung dịch phức xanh đậm, và lượng thuốc thử quyết định hiện tượng.', '[{"term": "水酸化銅", "reading": "すいさんかどう", "meaning": "hiđroxit đồng"}, {"term": "淡青色", "reading": "たんせいしょく", "meaning": "màu xanh nhạt"}, {"term": "沈殿", "reading": "ちんでん", "meaning": "kết tủa"}, {"term": "過剰", "reading": "かじょう", "meaning": "dư"}]'::jsonb, 10);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 11, '第四属の陽イオンは、H₂S(0.3 mol/L 酸性)共存下では沈殿が生じないが、(NH₄)₂S共存下では沈殿が生じる。', 'Các cation nhóm IV không tạo kết tủa khi có H₂S trong môi trường axit 0.3 mol/L, nhưng tạo kết tủa khi có (NH₄)₂S.', NULL, '○', 'Theo sơ đồ phân tích định tính cổ điển mà đề sử dụng, nhóm này gồm những ion như Zn²⁺, Mn²⁺, Ni²⁺ và Co²⁺. Trong môi trường axit, sự phân li H₂S bị ức chế nên nồng độ S²⁻ thấp, không đủ làm kết tủa các sulfua này. Thuốc thử (NH₄)₂S trong môi trường thích hợp cung cấp S²⁻ cao hơn. Không nhầm số nhóm giữa các sơ đồ phân loại khác nhau.', '[{"term": "第四属", "reading": "だいよんぞく", "meaning": "nhóm IV"}, {"term": "陽イオン", "reading": "ようイオン", "meaning": "cation"}, {"term": "共存下", "reading": "きょうぞんか", "meaning": "khi có mặt đồng thời"}, {"term": "硫化物", "reading": "りゅうかぶつ", "meaning": "sulfua"}]'::jsonb, 11);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 12, '重量分析は、電磁気的相互作用を利用し、原子・分子のイオンを質量の違いによって分析する手法である。', 'Phân tích khối lượng là phương pháp sử dụng tương tác điện từ để phân tích ion của nguyên tử và phân tử dựa trên sự khác nhau về khối lượng.', NULL, '×', 'Mô tả này gần với khối phổ, trong đó ion được phân biệt theo tỉ số khối lượng/điện tích m/z. Phân tích khối lượng (gravimetry) dựa trên việc cân khối lượng một dạng chất xác định, chẳng hạn kết tủa đã làm khô hoặc nung, rồi tính lượng chất cần phân tích theo tỉ lượng. Điểm dễ nhầm là 重量分析 khác 質量分析.', '[{"term": "重量分析", "reading": "じゅうりょうぶんせき", "meaning": "phân tích khối lượng"}, {"term": "質量分析", "reading": "しつりょうぶんせき", "meaning": "khối phổ"}, {"term": "電磁気的相互作用", "reading": "でんじきてきそうごさよう", "meaning": "tương tác điện từ"}, {"term": "質量", "reading": "しつりょう", "meaning": "khối lượng"}]'::jsonb, 12);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 13, '重量分析において、試料が恒量に達したかを確かめるには、1 g当たりにおける加熱前後の質量の差が3 mg以下であるかを調べればよい。', 'Trong phân tích khối lượng, để kiểm tra mẫu đã đạt khối lượng không đổi hay chưa, chỉ cần xem chênh lệch khối lượng trước và sau gia nhiệt có không quá 3 mg trên mỗi 1 g hay không.', NULL, '×', 'Mức 3 mg trên 1 g tương đương 0.3%, quá lớn để dùng như tiêu chí chung của cân phân tích chính xác. Khối lượng không đổi được kiểm tra bằng các chu kỳ gia nhiệt, làm nguội trong điều kiện quy định và cân lặp lại, so sánh hai lần cân liên tiếp. Giới hạn cụ thể phụ thuộc phương pháp và tiêu chuẩn; không tự áp một ngưỡng cho mọi phép thử. Câu sai ở tiêu chí 3 mg/g và cách khái quát nó.', '[{"term": "恒量", "reading": "こうりょう", "meaning": "khối lượng không đổi"}, {"term": "加熱前後", "reading": "かねつぜんご", "meaning": "trước và sau gia nhiệt"}, {"term": "質量の差", "reading": "しつりょうのさ", "meaning": "chênh lệch khối lượng"}, {"term": "以下", "reading": "いか", "meaning": "không quá"}]'::jsonb, 13);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 14, '試料溶液に過剰量の標準液を一定量加えて反応を完結させた後、余剰の標準液を他の種類の滴定液を用いて滴定し、分析種の量を間接的に求める方法を、逆滴定という。', 'Phương pháp thêm một lượng xác định dung dịch chuẩn dư vào dung dịch mẫu để phản ứng hoàn tất, sau đó dùng một dung dịch chuẩn độ khác chuẩn độ lượng dung dịch chuẩn còn dư, qua đó xác định gián tiếp lượng chất cần phân tích, được gọi là chuẩn độ ngược.', NULL, '○', 'Đây là định nghĩa chuẩn độ ngược. Lượng thuốc thử đã phản ứng với mẫu bằng lượng ban đầu trừ lượng còn dư; sau đó đổi sang lượng chất phân tích theo hệ số phản ứng. Phương pháp hữu ích khi phản ứng trực tiếp chậm hoặc khó xác định điểm kết thúc. Không lấy lượng thuốc thử ban đầu làm toàn bộ lượng đã phản ứng.', '[{"term": "逆滴定", "reading": "ぎゃくてきてい", "meaning": "chuẩn độ ngược"}, {"term": "余剰", "reading": "よじょう", "meaning": "phần dư"}, {"term": "分析種", "reading": "ぶんせきしゅ", "meaning": "chất cần phân tích"}, {"term": "完結", "reading": "かんけつ", "meaning": "hoàn tất"}]'::jsonb, 14);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 15, 'フェノールフタレインは、酸塩基指示薬として用いられ、アルカリ性(pH > 10.0)では紅色を呈する。', 'Phenolphthalein được dùng làm chỉ thị axit–bazơ và có màu đỏ hồng trong môi trường kiềm (pH > 10.0).', NULL, '○', 'Phenolphthalein không màu ở phía axit và chuyển sang hồng/đỏ hồng qua vùng chuyển màu khoảng pH 8.2–10.0. Trong cách hiểu của đề, phía kiềm sau vùng chuyển màu có dạng màu nên đáp án là đúng. Cần phân biệt vùng chuyển màu với một giá trị pH duy nhất; ở kiềm rất mạnh có thể xảy ra mất màu, nên không mở rộng phát biểu thành quy luật cho mọi pH lớn tùy ý.', '[{"term": "フェノールフタレイン", "reading": "フェノールフタレイン", "meaning": "phenolphthalein"}, {"term": "酸塩基指示薬", "reading": "さんえんきしじやく", "meaning": "chỉ thị axit–bazơ"}, {"term": "アルカリ性", "reading": "アルカリせい", "meaning": "tính kiềm"}, {"term": "紅色", "reading": "こうしょく", "meaning": "màu đỏ hồng"}]'::jsonb, 15);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 16, '吸光度は、試料を透過した光の強度と、試料を透過する前の光の強度との比を百分率で表した数値である。', 'Độ hấp thụ quang là giá trị biểu diễn bằng phần trăm tỉ số giữa cường độ ánh sáng đã truyền qua mẫu và cường độ ánh sáng trước khi truyền qua mẫu.', NULL, '×', 'Giá trị trong câu là độ truyền qua phần trăm: T% = 100I/I₀. Độ hấp thụ quang là A = log₁₀(I₀/I) = −log₁₀(I/I₀), với I₀ là cường độ tới và I là cường độ truyền qua. Chẳng hạn T = 0.1 tương ứng T% = 10% và A = 1; không được lấy 10 làm độ hấp thụ.', '[{"term": "吸光度", "reading": "きゅうこうど", "meaning": "độ hấp thụ quang"}, {"term": "透過", "reading": "とうか", "meaning": "truyền qua"}, {"term": "強度", "reading": "きょうど", "meaning": "cường độ"}, {"term": "百分率", "reading": "ひゃくぶんりつ", "meaning": "tỉ lệ phần trăm"}]'::jsonb, 16);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 17, '水の質量を測定した結果が2.0 × 10² gと記載されている場合、有効数字は2桁である。', 'Nếu kết quả đo khối lượng nước được ghi là 2.0 × 10² g, thì số chữ số có nghĩa là 2.', NULL, '○', 'Trong cách ghi khoa học này, phần 2.0 có hai chữ số có nghĩa: 2 và số 0 sau dấu thập phân. Thừa số 10² chỉ xác định bậc độ lớn, không làm tăng số chữ số có nghĩa. Không bỏ số 0 cuối vì nó thể hiện độ chính xác của phép đo.', '[{"term": "有効数字", "reading": "ゆうこうすうじ", "meaning": "chữ số có nghĩa"}, {"term": "桁", "reading": "けた", "meaning": "chữ số, hàng số"}, {"term": "測定", "reading": "そくてい", "meaning": "đo"}, {"term": "記載", "reading": "きさい", "meaning": "ghi, ghi chép"}]'::jsonb, 17);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 18, '二酸化炭素は、無色・無臭で空気よりも軽い気体である。', 'Cacbon đioxit là khí không màu, không mùi và nhẹ hơn không khí.', NULL, '×', 'CO₂ không màu và không mùi nhưng nặng hơn không khí ở cùng nhiệt độ và áp suất: khối lượng mol khoảng 44 g/mol, so với không khí trung bình khoảng 29 g/mol. Câu ghép chỉ cần một đặc tính sai là toàn câu sai. CO₂ có thể tích tụ tại chỗ thấp và làm giảm nồng độ oxy.', '[{"term": "二酸化炭素", "reading": "にさんかたんそ", "meaning": "cacbon đioxit"}, {"term": "無色", "reading": "むしょく", "meaning": "không màu"}, {"term": "無臭", "reading": "むしゅう", "meaning": "không mùi"}, {"term": "気体", "reading": "きたい", "meaning": "chất khí"}]'::jsonb, 18);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 19, '亜鉛イオン(Zn²⁺)を含む塩基性水溶液に硫化水素(H₂S)を吹き込むと、硫化亜鉛(ZnS)の黒色沈殿が生じる。', 'Khi sục hiđro sulfua (H₂S) vào dung dịch nước có tính bazơ chứa ion kẽm (Zn²⁺), kết tủa màu đen của kẽm sulfua (ZnS) hình thành.', NULL, '×', 'Zn²⁺ + S²⁻ → ZnS↓, nhưng ZnS là kết tủa trắng, không phải đen. Môi trường bazơ tăng nồng độ S²⁻ và thuận lợi cho kết tủa. Điểm dễ nhầm: nhiều sulfua kim loại như CuS có màu đen, nhưng không được suy màu đó cho tất cả sulfua.', '[{"term": "亜鉛イオン", "reading": "あえんイオン", "meaning": "ion kẽm"}, {"term": "塩基性", "reading": "えんきせい", "meaning": "tính bazơ"}, {"term": "硫化水素", "reading": "りゅうかすいそ", "meaning": "hiđro sulfua"}, {"term": "硫化亜鉛", "reading": "りゅうかあえん", "meaning": "kẽm sulfua"}]'::jsonb, 19);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 20, '炭酸水素ナトリウム水溶液は、弱酸性を示す。', 'Dung dịch nước của natri hiđrocacbonat có tính axit yếu.', NULL, '×', 'NaHCO₃ trong nước cho dung dịch có tính kiềm yếu. HCO₃⁻ là ion lưỡng tính, nhưng tác dụng nhận proton chiếm ưu thế trong dung dịch muối này. Điểm dễ nhầm là chữ 水素 trong tên không có nghĩa dung dịch nhất thiết có tính axit; phải xét cân bằng axit–bazơ.', '[{"term": "炭酸水素ナトリウム", "reading": "たんさんすいそナトリウム", "meaning": "natri hiđrocacbonat"}, {"term": "弱酸性", "reading": "じゃくさんせい", "meaning": "tính axit yếu"}, {"term": "弱塩基性", "reading": "じゃくえんきせい", "meaning": "tính bazơ yếu"}, {"term": "水溶液", "reading": "すいようえき", "meaning": "dung dịch nước"}]'::jsonb, 20);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 21, 'ふっ化水素、塩化水素、臭化水素、よう化水素などを総称してハロゲン化水素というが、常温ではいずれも無色・無臭の気体である。', 'Hiđro florua, hiđro clorua, hiđro bromua, hiđro iodua và các chất tương tự được gọi chung là hiđro halogenua; ở nhiệt độ thường, tất cả đều là khí không màu, không mùi.', NULL, '×', 'Các hiđro halogenua có mùi kích thích, nên 無臭 là sai. Ngoài ra, HF có nhiệt độ sôi gần nhiệt độ phòng, vì vậy trạng thái phụ thuộc nhiệt độ cụ thể và áp suất. Không dùng cách ngửi trực tiếp để nhận biết khí; trong câu này cần nhận ra từ tuyệt đối いずれも và tính chất không mùi không đúng.', '[{"term": "ふっ化水素", "reading": "ふっかすいそ", "meaning": "hiđro florua"}, {"term": "臭化水素", "reading": "しゅうかすいそ", "meaning": "hiđro bromua"}, {"term": "よう化水素", "reading": "ようかすいそ", "meaning": "hiđro iodua"}, {"term": "ハロゲン化水素", "reading": "ハロゲンかすいそ", "meaning": "hiđro halogenua"}]'::jsonb, 21);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 22, '分子内に1個の三重結合をもつ鎖式炭化水素をアルケンといい、一般式は、CₙH₂ₙで表される。', 'Hiđrocacbon mạch hở có một liên kết ba trong phân tử được gọi là anken, và được biểu diễn bằng công thức tổng quát CₙH₂ₙ.', NULL, '×', 'Mạch hở có một liên kết ba là ankin, công thức CₙH₂ₙ₋₂. Anken mạch hở có một liên kết đôi có công thức CₙH₂ₙ. Ví dụ etin C₂H₂ thuộc ankin, còn eten C₂H₄ thuộc anken. Câu sai cả tên nhóm và công thức đối với liên kết ba.', '[{"term": "三重結合", "reading": "さんじゅうけつごう", "meaning": "liên kết ba"}, {"term": "鎖式炭化水素", "reading": "さしきたんかすいそ", "meaning": "hiđrocacbon mạch hở"}, {"term": "アルケン", "reading": "アルケン", "meaning": "anken"}, {"term": "一般式", "reading": "いっぱんしき", "meaning": "công thức tổng quát"}]'::jsonb, 22);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 23, 'エタノールに金属ナトリウムを加えると、水素が発生する。', 'Khi thêm natri kim loại vào etanol, khí hiđro được sinh ra.', NULL, '○', 'Natri phản ứng với hiđro của nhóm −OH trong etanol, tạo natri etoxit và H₂: 2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂↑. Không nhầm khí sinh ra là oxy. Phản ứng tạo khí dễ cháy; đây là kiến thức phản ứng, không phải thao tác để tự thực hiện ngoài điều kiện thí nghiệm kiểm soát.', '[{"term": "エタノール", "reading": "エタノール", "meaning": "etanol"}, {"term": "金属ナトリウム", "reading": "きんぞくナトリウム", "meaning": "natri kim loại"}, {"term": "水素", "reading": "すいそ", "meaning": "hiđro"}, {"term": "発生", "reading": "はっせい", "meaning": "sinh ra"}]'::jsonb, 23);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 24, 'アルミニウム(Al)は、塩酸や水酸化ナトリウム水溶液に溶けて、水素を発生する。', 'Nhôm (Al) tan trong axit clohiđric hoặc dung dịch nước natri hiđroxit và sinh ra hiđro.', NULL, '○', 'Nhôm có thể phản ứng với axit cũng như dung dịch kiềm mạnh sau khi lớp oxit bảo vệ bị phá vỡ. Với axit: 2Al + 6HCl → 2AlCl₃ + 3H₂. Trong kiềm nước: 2Al + 2NaOH + 6H₂O → 2Na[Al(OH)₄] + 3H₂. Điểm dễ nhầm: không chỉ môi trường axit mới hòa tan nhôm.', '[{"term": "アルミニウム", "reading": "アルミニウム", "meaning": "nhôm"}, {"term": "塩酸", "reading": "えんさん", "meaning": "axit clohiđric"}, {"term": "水酸化ナトリウム", "reading": "すいさんかナトリウム", "meaning": "natri hiđroxit"}, {"term": "溶ける", "reading": "とける", "meaning": "tan"}]'::jsonb, 24);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 25, '塩化水素分子において、水素原子と塩素原子の結合は、主に共有結合である。', 'Trong phân tử hiđro clorua, liên kết giữa nguyên tử hiđro và nguyên tử clo chủ yếu là liên kết cộng hóa trị.', NULL, '○', 'Trong phân tử HCl, H và Cl dùng chung cặp electron, tạo liên kết cộng hóa trị có cực do độ âm điện khác nhau. Khi hòa tan vào nước, HCl ion hóa mạnh thành H₃O⁺ và Cl⁻. Không lấy hiện tượng ion hóa trong dung dịch để gọi liên kết bên trong phân tử HCl là liên kết ion.', '[{"term": "塩化水素", "reading": "えんかすいそ", "meaning": "hiđro clorua"}, {"term": "原子", "reading": "げんし", "meaning": "nguyên tử"}, {"term": "塩素", "reading": "えんそ", "meaning": "clo"}, {"term": "共有結合", "reading": "きょうゆうけつごう", "meaning": "liên kết cộng hóa trị"}]'::jsonb, 25);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 26, '塩酸と水酸化ナトリウムが反応するのは、中和反応である。', 'Phản ứng giữa axit clohiđric và natri hiđroxit là phản ứng trung hòa.', NULL, '○', 'Axit và bazơ phản ứng tạo muối và nước: HCl + NaOH → NaCl + H₂O. Phương trình ion rút gọn là H⁺ + OH⁻ → H₂O. Đây là trung hòa, không phải phản ứng oxi hóa–khử vì số oxi hóa các nguyên tố không thay đổi.', '[{"term": "中和反応", "reading": "ちゅうわはんのう", "meaning": "phản ứng trung hòa"}, {"term": "塩酸", "reading": "えんさん", "meaning": "axit clohiđric"}, {"term": "水酸化ナトリウム", "reading": "すいさんかナトリウム", "meaning": "natri hiđroxit"}, {"term": "反応", "reading": "はんのう", "meaning": "phản ứng"}]'::jsonb, 26);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 27, '不揮発性の溶質を含む溶媒の沸点は、それを含まない溶媒の沸点よりも低い。', 'Nhiệt độ sôi của dung môi chứa chất tan không bay hơi thấp hơn nhiệt độ sôi của dung môi không chứa chất tan đó.', NULL, '×', 'Chất tan không bay hơi làm giảm áp suất hơi của dung môi; tại cùng áp suất bên ngoài, cần nhiệt độ cao hơn để sôi. Đây là sự tăng nhiệt độ sôi: ΔTᵦ = Kᵦmb trong mô hình dung dịch loãng, hoặc ΔTᵦ = iKᵦmb nếu tính hệ số van ’t Hoff. mb là nồng độ molan, Kᵦ là hằng số của dung môi. Không nhầm với sự hạ nhiệt độ đông đặc.', '[{"term": "不揮発性", "reading": "ふきはつせい", "meaning": "không bay hơi"}, {"term": "溶質", "reading": "ようしつ", "meaning": "chất tan"}, {"term": "溶媒", "reading": "ようばい", "meaning": "dung môi"}, {"term": "沸点", "reading": "ふってん", "meaning": "nhiệt độ sôi"}]'::jsonb, 27);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 28, '食塩水が純水よりも凍りにくいのは、凝固点降下によるものである。', 'Nước muối khó đóng băng hơn nước tinh khiết là do sự hạ nhiệt độ đông đặc.', NULL, '○', 'Hòa tan muối làm nhiệt độ đông đặc của dung dịch thấp hơn nước tinh khiết. Với dung dịch loãng, độ hạ đông đặc được mô tả ΔT𝒻 = iK𝒻mb; i tính số tiểu phân hiệu dụng, K𝒻 là hằng số dung môi và mb là nồng độ molan. Ở một nhiệt độ mà nước tinh khiết đã đông, nước muối có thể vẫn lỏng. Không nhầm 凝固点降下 với 沸点上昇.', '[{"term": "食塩水", "reading": "しょくえんすい", "meaning": "nước muối"}, {"term": "純水", "reading": "じゅんすい", "meaning": "nước tinh khiết"}, {"term": "凍る", "reading": "こおる", "meaning": "đóng băng"}, {"term": "凝固点降下", "reading": "ぎょうこてんこうか", "meaning": "hạ nhiệt độ đông đặc"}]'::jsonb, 28);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 29, '油火災の消火には、りん酸アンモニウムを主剤とした粉末消火器を使用できる。', 'Có thể dùng bình chữa cháy bột có thành phần chính là amoni photphat để dập cháy dầu.', NULL, '○', 'Bột chữa cháy ABC gốc amoni photphat phù hợp với đám cháy dầu thuộc loại B khi thiết bị có ghi khả năng chữa loại B. Bột ức chế phản ứng cháy và giúp dập lửa. Không nhầm việc có thể dùng loại bình này với việc mọi loại bột hoặc mọi tình huống cháy dầu đều xử lý như nhau; chọn bình theo nhãn phân loại và điều kiện thực tế.', '[{"term": "油火災", "reading": "あぶらかさい", "meaning": "đám cháy dầu"}, {"term": "消火", "reading": "しょうか", "meaning": "dập lửa"}, {"term": "りん酸アンモニウム", "reading": "りんさんアンモニウム", "meaning": "amoni photphat"}, {"term": "粉末消火器", "reading": "ふんまつしょうかき", "meaning": "bình chữa cháy bột"}]'::jsonb, 29);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 30, '水素の高圧ガスボンベは、黒色に塗られている。', 'Bình khí hiđro cao áp được sơn màu đen.', NULL, '×', 'Trong quy định màu bình khí thông thường tại Nhật Bản, hiđro là đỏ và oxy là đen. Vì thế phát biểu đã nhầm hai khí. Quy định có các loại bình được miễn sơn màu; khi nhận biết thực tế phải đọc tên khí và nhãn, không chỉ nhìn màu. Trong phạm vi câu thi, đối chiếu cặp 水素＝赤色 và 酸素＝黒色.', '[{"term": "水素", "reading": "すいそ", "meaning": "hiđro"}, {"term": "高圧ガスボンベ", "reading": "こうあつガスボンベ", "meaning": "bình khí cao áp"}, {"term": "黒色", "reading": "こくしょく", "meaning": "màu đen"}, {"term": "赤色", "reading": "せきしょく", "meaning": "màu đỏ"}]'::jsonb, 30);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 1, '日本産業規格(JIS)のろ紙(化学分析用)において、ろ紙の種類は、定性分析用と定量分析用が規定されている。', 'Trong tiêu chuẩn công nghiệp Nhật Bản (JIS) về giấy lọc dùng cho phân tích hóa học, các loại giấy lọc được quy định gồm loại dùng cho phân tích định tính và loại dùng cho phân tích định lượng.', NULL, '○', 'Giấy lọc phân tích được phân biệt theo mục đích định tính và định lượng. Với phân tích định lượng khối lượng, lượng tro còn lại sau nung phải được kiểm soát để không làm tăng khối lượng đo. Điểm dễ nhầm: không chọn giấy lọc chỉ theo tốc độ lọc mà còn theo mục đích và khả năng giữ hạt.', '[{"term": "日本産業規格", "reading": "にほんさんぎょうきかく", "meaning": "tiêu chuẩn công nghiệp Nhật Bản"}, {"term": "ろ紙", "reading": "ろし", "meaning": "giấy lọc"}, {"term": "定性分析", "reading": "ていせいぶんせき", "meaning": "phân tích định tính"}, {"term": "定量分析", "reading": "ていりょうぶんせき", "meaning": "phân tích định lượng"}]'::jsonb, 31);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 2, 'ほうけい酸塩ガラス製器具は、一般に、高い化学的耐久性を示す。', 'Dụng cụ bằng thủy tinh borosilicat nhìn chung có độ bền hóa học cao.', NULL, '○', 'Thủy tinh borosilicat thường dùng cho dụng cụ phòng thí nghiệm nhờ bền hóa học với nhiều dung dịch và chịu sốc nhiệt tốt. Từ 一般に thể hiện tính chất nói chung, không có nghĩa chịu được mọi hóa chất. HF và kiềm mạnh, đặc biệt khi nóng, có thể ăn mòn thủy tinh.', '[{"term": "ほうけい酸塩ガラス", "reading": "ほうけいさんえんガラス", "meaning": "thủy tinh borosilicat"}, {"term": "器具", "reading": "きぐ", "meaning": "dụng cụ"}, {"term": "化学的耐久性", "reading": "かがくてきたいきゅうせい", "meaning": "độ bền hóa học"}, {"term": "一般に", "reading": "いっぱんに", "meaning": "nhìn chung"}]'::jsonb, 32);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 3, 'ガスクロマトグラフを用いて有機化合物を分析する際に、熱伝導度検出器(TCD)を使用するよりも水素炎イオン化検出器(FID)を使用した方が、高い感度で分析できる。', 'Khi dùng máy sắc ký khí để phân tích hợp chất hữu cơ, dùng đầu dò ion hóa ngọn lửa hiđro (FID) cho độ nhạy cao hơn dùng đầu dò dẫn nhiệt (TCD).', NULL, '○', 'FID thường có độ nhạy cao đối với nhiều hợp chất hữu cơ, còn TCD phát hiện dựa trên chênh lệch độ dẫn nhiệt so với khí mang và thường kém nhạy hơn. TCD có phạm vi phát hiện rộng, gồm nhiều khí mà FID không đáp ứng. Không hiểu đáp án thành FID nhạy với mọi chất hữu cơ không có ngoại lệ; khả năng đáp ứng phụ thuộc cấu trúc chất và điều kiện đo.', '[{"term": "ガスクロマトグラフ", "reading": "ガスクロマトグラフ", "meaning": "máy sắc ký khí"}, {"term": "熱伝導度検出器", "reading": "ねつでんどうどけんしゅつき", "meaning": "đầu dò dẫn nhiệt"}, {"term": "水素炎イオン化検出器", "reading": "すいそえんイオンかけんしゅつき", "meaning": "đầu dò ion hóa ngọn lửa"}, {"term": "感度", "reading": "かんど", "meaning": "độ nhạy"}]'::jsonb, 33);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 4, '濃硫酸を希釈するときは、水に濃硫酸を少量ずつ加える。', 'Khi pha loãng axit sulfuric đặc, thêm từng lượng nhỏ axit sulfuric đặc vào nước.', NULL, '○', 'Pha loãng H₂SO₄ đặc tỏa nhiệt mạnh. Thêm axit từ từ vào lượng nước lớn hơn, khuấy và làm mát theo quy trình giúp phân tán nhiệt. Nếu rót nước vào axit đặc, lớp nước nhỏ có thể nóng và sôi đột ngột gây bắn axit. Điểm quyết định của câu là chiều thêm: axit vào nước.', '[{"term": "濃硫酸", "reading": "のうりゅうさん", "meaning": "axit sulfuric đặc"}, {"term": "希釈", "reading": "きしゃく", "meaning": "pha loãng"}, {"term": "少量ずつ", "reading": "しょうりょうずつ", "meaning": "từng lượng nhỏ"}, {"term": "加える", "reading": "くわえる", "meaning": "thêm vào"}]'::jsonb, 34);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 5, '実験で残った0.1 mol/Lの塩酸は、少量であれば流しにそのまま流してもよい。', 'Axit clohiđric 0.1 mol/L còn lại sau thí nghiệm, nếu chỉ có lượng nhỏ, có thể đổ trực tiếp vào bồn rửa.', NULL, '×', 'Không được mặc nhiên đổ trực tiếp chỉ vì nồng độ thấp hoặc lượng nhỏ. Phải thu gom, phân loại và xử lý theo quy trình chất thải của cơ sở; có thể còn chất nhiễm bẩn khác trong dung dịch. Trung hòa hoặc thải bỏ chỉ được thực hiện khi quy trình và điều kiện cho phép. Từ そのまま là bẫy quan trọng trong câu.', '[{"term": "塩酸", "reading": "えんさん", "meaning": "axit clohiđric"}, {"term": "少量", "reading": "しょうりょう", "meaning": "lượng nhỏ"}, {"term": "流し", "reading": "ながし", "meaning": "bồn rửa"}, {"term": "廃液", "reading": "はいえき", "meaning": "dung dịch thải"}]'::jsonb, 35);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 6, '過マンガン酸カリウム標準水溶液の調製の際は、過マンガン酸カリウムの溶解後、直ちに標定しなければならない。', 'Khi pha dung dịch nước chuẩn kali pemanganat, phải chuẩn hóa ngay sau khi hòa tan kali pemanganat.', NULL, '×', 'Không chuẩn hóa ngay. Dung dịch mới pha có thể tiếp tục phản ứng với tạp chất khử và tạo MnO₂, làm đổi nồng độ. Quy trình thường yêu cầu xử lý, để ổn định, loại MnO₂ bằng dụng cụ phù hợp rồi mới chuẩn hóa bằng chất chuẩn. Thời gian và điều kiện cụ thể theo phương pháp; điểm sai của câu là bắt buộc 直ちに.', '[{"term": "過マンガン酸カリウム", "reading": "かマンガンさんカリウム", "meaning": "kali pemanganat"}, {"term": "標定", "reading": "ひょうてい", "meaning": "chuẩn hóa dung dịch"}, {"term": "溶解後", "reading": "ようかいご", "meaning": "sau khi hòa tan"}, {"term": "直ちに", "reading": "ただちに", "meaning": "ngay lập tức"}]'::jsonb, 36);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 7, 'キレート滴定に用いるエチレンジアミン四酢酸二ナトリウム(EDTA)標準溶液を調製する際は、試薬を強熱して和水を揮散させてからひょう量する。', 'Khi pha dung dịch chuẩn đinatri etylenđiamintetraaxetat (EDTA) dùng cho chuẩn độ tạo phức, nung mạnh thuốc thử để làm bay hơi nước hydrat hóa rồi mới cân.', NULL, '×', 'Đinatri EDTA thường được sử dụng ở dạng đihydrat với thành phần xác định. Không nung mạnh để đuổi nước kết tinh vì có thể làm thay đổi dạng chất và gây phân hủy. Cần xử lý ở điều kiện quy định cho thuốc thử, cân theo đúng dạng hydrat và chuẩn hóa khi cần. Điểm dễ nhầm: làm khô có kiểm soát không đồng nghĩa với 強熱.', '[{"term": "キレート滴定", "reading": "キレートてきてい", "meaning": "chuẩn độ tạo phức"}, {"term": "四酢酸二ナトリウム", "reading": "しさくさんにナトリウム", "meaning": "tetraaxetat đinatri"}, {"term": "強熱", "reading": "きょうねつ", "meaning": "nung mạnh"}, {"term": "和水", "reading": "わすい", "meaning": "nước hydrat hóa"}, {"term": "ひょう量", "reading": "ひょうりょう", "meaning": "cân"}]'::jsonb, 37);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Strategy', 8, 'サンプリングとは、母集団から分析・試験を目的とした試料を取る操作をいう。', 'Lấy mẫu là thao tác lấy một mẫu từ tổng thể nhằm mục đích phân tích hoặc thử nghiệm.', NULL, '○', 'Định nghĩa đúng. Mẫu phải được lấy bằng kế hoạch phù hợp để đại diện cho tổng thể cần đánh giá, đồng thời tránh nhiễm bẩn và biến đổi. Sai số lấy mẫu có thể lớn dù phép phân tích rất chính xác. Phân biệt tổng thể 母集団 với phần nhỏ được lấy làm 試料.', '[{"term": "サンプリング", "reading": "サンプリング", "meaning": "lấy mẫu"}, {"term": "母集団", "reading": "ぼしゅうだん", "meaning": "tổng thể"}, {"term": "試料", "reading": "しりょう", "meaning": "mẫu"}, {"term": "操作", "reading": "そうさ", "meaning": "thao tác"}]'::jsonb, 38);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 9, 'アセトンに、よう素と水酸化アルカリ又は炭酸アルカリ水溶液を加えて温めると、黄色沈殿が生じる。', 'Khi thêm iod và dung dịch nước hiđroxit kim loại kiềm hoặc cacbonat kim loại kiềm vào axeton rồi làm ấm, kết tủa màu vàng hình thành.', NULL, '○', 'Axeton có nhóm metyl xeton CH₃CO−, cho phản ứng iodoform với iod trong môi trường kiềm. Kết tủa vàng là CHI₃. Phương trình với OH⁻: CH₃COCH₃ + 3I₂ + 4OH⁻ → CHI₃↓ + CH₃COO⁻ + 3I⁻ + 3H₂O. Không nhầm màu vàng này với kết tủa của một muối iodua kim loại.', '[{"term": "アセトン", "reading": "アセトン", "meaning": "axeton"}, {"term": "よう素", "reading": "ようそ", "meaning": "iod"}, {"term": "炭酸アルカリ", "reading": "たんさんアルカリ", "meaning": "cacbonat kim loại kiềm"}, {"term": "黄色沈殿", "reading": "おうしょくちんでん", "meaning": "kết tủa vàng"}]'::jsonb, 39);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 10, '炭酸カルシウムは、水に溶けにくいが、二酸化炭素を含んだ水には溶けやすくなる。', 'Canxi cacbonat khó tan trong nước, nhưng trở nên dễ tan hơn trong nước chứa cacbon đioxit.', NULL, '○', 'CO₂ hòa tan tạo môi trường axit yếu, thúc đẩy hòa tan CaCO₃ thành các ion canxi và hiđrocacbonat: CaCO₃ + CO₂ + H₂O ⇌ Ca²⁺ + 2HCO₃⁻. Cần phân biệt cacbonat ít tan với hiđrocacbonat tồn tại trong dung dịch. Khi CO₂ thoát ra, cân bằng có thể chuyển ngược và CaCO₃ kết tủa.', '[{"term": "炭酸カルシウム", "reading": "たんさんカルシウム", "meaning": "canxi cacbonat"}, {"term": "二酸化炭素", "reading": "にさんかたんそ", "meaning": "cacbon đioxit"}, {"term": "溶けにくい", "reading": "とけにくい", "meaning": "khó tan"}, {"term": "含んだ", "reading": "ふくんだ", "meaning": "có chứa"}]'::jsonb, 40);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 11, '水酸化アルミニウムは、水酸化ナトリウム水溶液よりもアンモニア水に溶けやすい。', 'Hiđroxit nhôm dễ tan trong nước amoniac hơn trong dung dịch nước natri hiđroxit.', NULL, '×', 'Al(OH)₃ là hiđroxit lưỡng tính, tan trong kiềm mạnh dư: Al(OH)₃ + OH⁻ → [Al(OH)₄]⁻. Nước amoniac là bazơ yếu và không hòa tan Al(OH)₃ tốt như dung dịch NaOH trong phép thử này. Điểm dễ nhầm là không phải hiđroxit kim loại nào cũng tan trong NH₃ dư do tạo phức.', '[{"term": "水酸化アルミニウム", "reading": "すいさんかアルミニウム", "meaning": "hiđroxit nhôm"}, {"term": "アンモニア水", "reading": "アンモニアすい", "meaning": "nước amoniac"}, {"term": "両性", "reading": "りょうせい", "meaning": "lưỡng tính"}, {"term": "溶けやすい", "reading": "とけやすい", "meaning": "dễ tan"}]'::jsonb, 41);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 12, '重量分析とは、定量しようとする成分を一定の組成の純物質として分離し、その質量又は残分の質量から分析種の量を求める定量分析のことである。', 'Phân tích khối lượng là phương pháp phân tích định lượng trong đó thành phần cần định lượng được tách dưới dạng chất tinh khiết có thành phần xác định, rồi lượng chất phân tích được tính từ khối lượng chất đó hoặc khối lượng phần còn lại.', NULL, '○', 'Đây là định nghĩa đúng. Khi dạng cân có công thức xác định, có thể đổi khối lượng cân sang lượng chất phân tích bằng tỉ lượng. Cần tách sạch tạp chất, xử lý để dạng cân ổn định và cân chính xác. Không nhầm với khối phổ, là phương pháp khảo sát các ion theo m/z.', '[{"term": "重量分析", "reading": "じゅうりょうぶんせき", "meaning": "phân tích khối lượng"}, {"term": "組成", "reading": "そせい", "meaning": "thành phần"}, {"term": "純物質", "reading": "じゅんぶっしつ", "meaning": "chất tinh khiết"}, {"term": "残分", "reading": "ざんぶん", "meaning": "phần còn lại"}]'::jsonb, 42);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 13, '重量分析において、不純物を取り除くための洗浄は、少量の洗液で回数を多くするよりも、多量の洗液で回数を少なくした方が効率が良い。', 'Trong phân tích khối lượng, việc rửa để loại tạp chất hiệu quả hơn khi dùng nhiều dung dịch rửa trong ít lần so với dùng ít dung dịch rửa trong nhiều lần.', NULL, '×', 'Với cùng tổng thể tích dung dịch rửa, chia thành nhiều phần nhỏ thường loại chất bẩn hòa tan hiệu quả hơn. Sau mỗi lần rửa, dung dịch bẩn được thay bằng dung dịch mới, tiếp tục giảm lượng tạp còn lại. Phải chọn dung dịch rửa phù hợp để hạn chế hòa tan kết tủa hoặc peptit hóa. Câu đã đảo ngược quy tắc so sánh.', '[{"term": "不純物", "reading": "ふじゅんぶつ", "meaning": "tạp chất"}, {"term": "取り除く", "reading": "とりのぞく", "meaning": "loại bỏ"}, {"term": "洗液", "reading": "せんえき", "meaning": "dung dịch rửa"}, {"term": "効率", "reading": "こうりつ", "meaning": "hiệu quả"}]'::jsonb, 43);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 14, '濃度C<sub>Fe³⁺</sub> [mol/L]のFe³⁺と、C<sub>Fe²⁺</sub> [mol/L]のFe²⁺を含む混合溶液の25 ℃における電極電位Eは、標準酸化還元電位をE⁰とすれば、次の式で表すことができる。
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 15, 'Zn(OH)₂の沈殿にアンモニア水を過剰に加えると、[Zn(NH₃)₄]²⁺(テトラアンミン亜鉛(II)イオン)ができる。', 'Khi thêm dư nước amoniac vào kết tủa Zn(OH)₂, ion [Zn(NH₃)₄]²⁺ (ion tetraammin kẽm(II)) được tạo thành.', NULL, '○', 'Zn(OH)₂ có thể hòa tan trong NH₃ dư nhờ tạo phức ammin tan: Zn(OH)₂ + 4NH₃ ⇌ [Zn(NH₃)₄]²⁺ + 2OH⁻. Số phối tử NH₃ là 4 và điện tích phức là 2+. Không nhầm với hiđroxit nhôm, vốn không tan tốt trong NH₃ dư theo phép thử của câu 11.', '[{"term": "沈殿", "reading": "ちんでん", "meaning": "kết tủa"}, {"term": "過剰", "reading": "かじょう", "meaning": "dư"}, {"term": "テトラアンミン亜鉛", "reading": "テトラアンミンあえん", "meaning": "tetraammin kẽm"}, {"term": "錯イオン", "reading": "さくイオン", "meaning": "ion phức"}]'::jsonb, 45);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Technology', 16, '吸光度とは、試料を透過した光の強度と、試料を透過する前の光の強度との比を常用対数で表した数値をいう。', 'Độ hấp thụ quang là giá trị biểu diễn bằng logarit thập phân của tỉ số giữa cường độ ánh sáng truyền qua mẫu và cường độ ánh sáng trước khi truyền qua mẫu.', NULL, '○', 'Đáp án chính thức là đúng, nhưng câu chữ về chiều của tỉ số có thể gây nhầm. Công thức cần dùng là A = log₁₀(I₀/I) = −log₁₀(I/I₀), với I₀ là cường độ trước mẫu và I là cường độ sau mẫu. Nếu đọc tỉ số đúng theo thứ tự kể trong câu là I/I₀, phải có dấu trừ; log₁₀(I/I₀) đơn thuần không phải độ hấp thụ quang thông thường. Giữ đáp án chính thức, đồng thời ghi nhớ công thức có chiều và dấu chính xác để tính toán.', '[{"term": "吸光度", "reading": "きゅうこうど", "meaning": "độ hấp thụ quang"}, {"term": "常用対数", "reading": "じょうようたいすう", "meaning": "logarit thập phân"}, {"term": "比", "reading": "ひ", "meaning": "tỉ số"}, {"term": "透過した光", "reading": "とうかしたひかり", "meaning": "ánh sáng đã truyền qua"}]'::jsonb, 46);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 17, '蒸留水の質量を測定したところ36 gで、水の分子量を18.015としてモル数を計算した結果、1.99833…となったとき、この蒸留水のモル数は有効数字に留意すれば1.9983 molである。', 'Khi đo khối lượng nước cất thu được 36 g, lấy khối lượng phân tử của nước là 18.015 để tính số mol thì được 1.99833…; khi chú ý đến chữ số có nghĩa, số mol của lượng nước cất này là 1.9983 mol.', NULL, '×', '36 g có hai chữ số có nghĩa, còn 18.015 có năm. Phép chia phải báo kết quả theo dữ liệu có ít chữ số có nghĩa nhất: n = 36/18.015 ≈ 1.99833 mol, làm tròn hai chữ số có nghĩa thành 2.0 mol. 1.9983 mol có năm chữ số có nghĩa nên thể hiện độ chính xác vượt dữ liệu khối lượng. Dấu kéo dài số thập phân trong đề là nội dung gốc, không phải phần bị rút gọn.', '[{"term": "蒸留水", "reading": "じょうりゅうすい", "meaning": "nước cất"}, {"term": "分子量", "reading": "ぶんしりょう", "meaning": "khối lượng phân tử"}, {"term": "モル数", "reading": "モルすう", "meaning": "số mol"}, {"term": "留意", "reading": "りゅうい", "meaning": "chú ý"}]'::jsonb, 47);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 18, '1.0 mol/Lの希硫酸10 mLを中和するには、0.5 mol/Lの水酸化ナトリウム水溶液が40 mL必要である。', 'Để trung hòa 10 mL axit sulfuric loãng 1.0 mol/L, cần 40 mL dung dịch nước natri hiđroxit 0.5 mol/L.', NULL, '○', 'H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O. Số mol H₂SO₄ là 1.0 × 0.010 = 0.010 mol, nên cần 0.020 mol NaOH. V = 0.020/0.5 = 0.040 L = 40 mL. Điểm dễ nhầm: một mol H₂SO₄ cần hai mol NaOH khi trung hòa hoàn toàn, không dùng tỉ lệ 1:1.', '[{"term": "希硫酸", "reading": "きりゅうさん", "meaning": "axit sulfuric loãng"}, {"term": "中和", "reading": "ちゅうわ", "meaning": "trung hòa"}, {"term": "必要", "reading": "ひつよう", "meaning": "cần thiết"}, {"term": "水酸化ナトリウム", "reading": "すいさんかナトリウム", "meaning": "natri hiđroxit"}]'::jsonb, 48);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 19, 'HeやArなどの18族元素は、貴ガス(希ガス)と呼ばれる。', 'Các nguyên tố nhóm 18 như He và Ar được gọi là khí quý (khí hiếm).', NULL, '○', 'He và Ar thuộc nhóm 18 của bảng tuần hoàn. Các nguyên tố nhóm này có lớp electron ngoài cùng bền và nhìn chung ít phản ứng; He có cấu hình ngoài cùng 1s². Không diễn giải tên khí quý thành tuyệt đối không thể tạo hợp chất, vì một số nguyên tố nặng như xenon có hợp chất đã biết.', '[{"term": "18族元素", "reading": "じゅうはちぞくげんそ", "meaning": "nguyên tố nhóm 18"}, {"term": "貴ガス", "reading": "きガス", "meaning": "khí quý"}, {"term": "希ガス", "reading": "きガス", "meaning": "khí hiếm"}, {"term": "元素", "reading": "げんそ", "meaning": "nguyên tố"}]'::jsonb, 49);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 20, 'アルカリ金属の水酸化物は、白色の固体で水によく溶け、その水溶液は、強酸性を示す。', 'Các hiđroxit của kim loại kiềm là chất rắn màu trắng, tan tốt trong nước, và dung dịch nước của chúng có tính axit mạnh.', NULL, '×', 'Các hiđroxit kim loại kiềm như NaOH và KOH cho dung dịch có tính kiềm mạnh vì tạo OH⁻. Câu sai ở 強酸性; kiến thức đúng cần đối chiếu là 強塩基性. Trong câu ghép, các phần về màu và độ tan có thể đúng nhưng một phần sai khiến toàn câu sai.', '[{"term": "アルカリ金属", "reading": "アルカリきんぞく", "meaning": "kim loại kiềm"}, {"term": "水酸化物", "reading": "すいさんかぶつ", "meaning": "hiđroxit"}, {"term": "固体", "reading": "こたい", "meaning": "chất rắn"}, {"term": "強酸性", "reading": "きょうさんせい", "meaning": "tính axit mạnh"}]'::jsonb, 50);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 21, '酸素とオゾンは、いずれも酸素の同素体である。', 'Oxy và ozon đều là các dạng thù hình của nguyên tố oxy.', NULL, '○', 'O₂ và O₃ được cấu tạo từ cùng nguyên tố oxy nhưng khác số nguyên tử trong phân tử và khác tính chất, nên là các dạng thù hình. Không nhầm 同素体 với 同位体: đồng vị khác số nơtron, còn dạng thù hình khác cấu trúc của đơn chất.', '[{"term": "酸素", "reading": "さんそ", "meaning": "oxy"}, {"term": "オゾン", "reading": "オゾン", "meaning": "ozon"}, {"term": "同素体", "reading": "どうそたい", "meaning": "dạng thù hình"}, {"term": "同位体", "reading": "どういたい", "meaning": "đồng vị"}]'::jsonb, 51);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 22, 'フェノール(C₆H₅OH)の水溶液は、弱塩基性を示す。', 'Dung dịch nước của phenol (C₆H₅OH) có tính bazơ yếu.', NULL, '×', 'Phenol là axit yếu, có thể nhường proton của nhóm −OH: C₆H₅OH ⇌ C₆H₅O⁻ + H⁺. Ion phenoxit được ổn định bởi cộng hưởng. Vì vậy câu phải là 弱酸性, không phải 弱塩基性. Không suy rằng mọi hợp chất chứa OH đều là bazơ như hiđroxit kim loại.', '[{"term": "フェノール", "reading": "フェノール", "meaning": "phenol"}, {"term": "弱塩基性", "reading": "じゃくえんきせい", "meaning": "tính bazơ yếu"}, {"term": "弱酸性", "reading": "じゃくさんせい", "meaning": "tính axit yếu"}, {"term": "水溶液", "reading": "すいようえき", "meaning": "dung dịch nước"}]'::jsonb, 52);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 23, '分子内に1個の三重結合をもつ鎖式炭化水素であるアルキンの一般式は、CₙH₂ₙ₋₂である。', 'Công thức tổng quát của ankin, là hiđrocacbon mạch hở có một liên kết ba trong phân tử, là CₙH₂ₙ₋₂.', NULL, '○', 'Điều kiện mạch hở và có một liên kết ba dẫn đến công thức CₙH₂ₙ₋₂. So với ankan CₙH₂ₙ₊₂, một liên kết ba làm giảm bốn H. Ví dụ n = 2 cho C₂H₂, n = 3 cho C₃H₄. Không áp công thức này cho mọi hiđrocacbon có thêm vòng hoặc nhiều liên kết bội.', '[{"term": "アルキン", "reading": "アルキン", "meaning": "ankin"}, {"term": "三重結合", "reading": "さんじゅうけつごう", "meaning": "liên kết ba"}, {"term": "鎖式炭化水素", "reading": "さしきたんかすいそ", "meaning": "hiđrocacbon mạch hở"}, {"term": "分子内", "reading": "ぶんしない", "meaning": "trong phân tử"}]'::jsonb, 53);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 24, 'アニリン(C₆H₅NH₂)は、芳香族アミンで、水にわずかに溶け、弱塩基性を示す。', 'Anilin (C₆H₅NH₂) là amin thơm, ít tan trong nước và có tính bazơ yếu.', NULL, '○', 'Cặp electron tự do trên N có thể nhận proton nên anilin là bazơ. Do liên hợp với vòng benzen, khả năng nhận proton giảm so với nhiều amin no; vì vậy tính bazơ yếu. Anilin ít tan trong nước, nhưng khi phản ứng với axit tạo muối anilinium thì độ tan tăng. Không nhầm tính axit yếu của phenol với tính bazơ yếu của anilin.', '[{"term": "アニリン", "reading": "アニリン", "meaning": "anilin"}, {"term": "芳香族アミン", "reading": "ほうこうぞくアミン", "meaning": "amin thơm"}, {"term": "わずかに", "reading": "わずかに", "meaning": "một ít"}, {"term": "弱塩基性", "reading": "じゃくえんきせい", "meaning": "tính bazơ yếu"}]'::jsonb, 54);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 25, '一定の温度のもとで、気体の体積は、圧力に比例する。', 'Ở nhiệt độ không đổi, thể tích của chất khí tỉ lệ thuận với áp suất.', NULL, '×', 'Với lượng khí xác định ở nhiệt độ không đổi trong mô hình khí lý tưởng, định luật Boyle cho pV = hằng số, tức V tỉ lệ nghịch với p. Tăng áp suất gấp đôi thì thể tích giảm còn một nửa. Câu đã nhầm 比例 với 反比例; điều kiện lượng khí không đổi cũng phải được giữ khi áp dụng.', '[{"term": "一定の温度", "reading": "いっていのおんど", "meaning": "nhiệt độ không đổi"}, {"term": "体積", "reading": "たいせき", "meaning": "thể tích"}, {"term": "圧力", "reading": "あつりょく", "meaning": "áp suất"}, {"term": "反比例", "reading": "はんぴれい", "meaning": "tỉ lệ nghịch"}]'::jsonb, 55);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 26, '2NO₂ ⇄ N₂O₄の反応において、圧力を高くすると、平衡は左式側に移動する。', 'Trong phản ứng 2NO₂ ⇄ N₂O₄, khi tăng áp suất, cân bằng chuyển về phía vế trái.', NULL, '×', 'Khi tăng áp suất bằng cách nén hệ khí ở nhiệt độ không đổi, cân bằng chuyển về phía có ít mol khí hơn: vế phải có 1 mol N₂O₄ so với 2 mol NO₂ ở vế trái. Vì vậy chuyển sang phải. Cần phân biệt nén hỗn hợp với thêm khí trơ ở thể tích không đổi, vốn không nhất thiết làm đổi các áp suất riêng phần.', '[{"term": "平衡", "reading": "へいこう", "meaning": "cân bằng"}, {"term": "左式側", "reading": "さしきがわ", "meaning": "phía vế trái"}, {"term": "移動", "reading": "いどう", "meaning": "dịch chuyển"}, {"term": "圧力", "reading": "あつりょく", "meaning": "áp suất"}]'::jsonb, 56);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 27, '圧力が同じであれば、3%の食塩水の沸点は、水の沸点よりも高い。', 'Nếu áp suất bằng nhau, nhiệt độ sôi của nước muối 3% cao hơn nhiệt độ sôi của nước.', NULL, '○', 'Muối là chất tan không bay hơi, làm giảm áp suất hơi của nước. Vì vậy ở cùng áp suất ngoài, dung dịch phải nóng hơn nước tinh khiết mới sôi. Câu chỉ yêu cầu so sánh, không cung cấp đủ quy ước nồng độ và dữ kiện để tính chính xác mức tăng; không tự chuyển 3% thành một định nghĩa chưa được nêu.', '[{"term": "食塩水", "reading": "しょくえんすい", "meaning": "nước muối"}, {"term": "沸点", "reading": "ふってん", "meaning": "nhiệt độ sôi"}, {"term": "圧力", "reading": "あつりょく", "meaning": "áp suất"}, {"term": "高い", "reading": "たかい", "meaning": "cao"}]'::jsonb, 57);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 28, '溶解度積は、難溶性の塩における溶解度の目安となり、溶解度が低い塩ほど大きくなる。', 'Tích số tan là chỉ dấu về độ tan của các muối ít tan, và muối có độ tan càng thấp thì tích số tan càng lớn.', NULL, '×', 'Với muối AB ⇌ A⁺ + B⁻ trong nước tinh khiết và bỏ qua phản ứng phụ, Ksp = [A⁺][B⁻] = s²; độ tan s thấp tương ứng Ksp nhỏ. Câu đã nói ngược. Khi so sánh muối có tỉ lượng khác nhau, phải viết biểu thức riêng: với AB₂ thì Ksp = [A²⁺][B⁻]² = 4s³. Không xếp độ tan chỉ từ trị số Ksp mà bỏ qua tỉ lượng, ion chung và pH.', '[{"term": "溶解度積", "reading": "ようかいどせき", "meaning": "tích số tan"}, {"term": "難溶性", "reading": "なんようせい", "meaning": "ít tan"}, {"term": "塩", "reading": "えん", "meaning": "muối"}, {"term": "目安", "reading": "めやす", "meaning": "chỉ dấu, mốc tham khảo"}]'::jsonb, 58);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 29, '酸素の高圧ガスボンベは、黒色に塗られている。', 'Bình khí oxy cao áp được sơn màu đen.', NULL, '○', 'Trong quy định màu bình khí thông thường của Nhật Bản, oxy là màu đen; hiđro là màu đỏ. Vì thế đáp án đúng trong phạm vi câu thi. Có loại bình được miễn yêu cầu sơn màu, nên khi sử dụng thực tế cần đọc nhãn tên khí và thông tin bình thay vì chỉ dựa vào màu.', '[{"term": "酸素", "reading": "さんそ", "meaning": "oxy"}, {"term": "高圧ガスボンベ", "reading": "こうあつガスボンベ", "meaning": "bình khí cao áp"}, {"term": "黒色", "reading": "こくしょく", "meaning": "màu đen"}, {"term": "塗られている", "reading": "ぬられている", "meaning": "được sơn"}]'::jsonb, 59);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', 'Management', 30, '液体窒素などの低温液化ガスを取り扱う場合、専用の保護手袋などを着用し、低温液化ガスが直接皮膚、眼、手足などに触れないようにする。', 'Khi thao tác với khí hóa lỏng ở nhiệt độ thấp như nitơ lỏng, phải đeo găng bảo hộ chuyên dụng và các đồ bảo hộ thích hợp, đồng thời tránh để khí hóa lỏng ở nhiệt độ thấp tiếp xúc trực tiếp với da, mắt, tay chân và các bộ phận tương tự.', NULL, '○', 'Nitơ lỏng có nhiệt độ cực thấp, gây bỏng lạnh khi tiếp xúc. Dùng găng dành cho chất lỏng lạnh sâu và bảo vệ mắt/mặt theo quy trình để giảm nguy cơ bắn tóe. Găng thông thường không thay thế găng chuyên dụng. Khí bay hơi còn có thể làm thiếu oxy trong không gian kín, nên việc tránh tiếp xúc không thay thế yêu cầu thông gió.', '[{"term": "液体窒素", "reading": "えきたいちっそ", "meaning": "nitơ lỏng"}, {"term": "低温液化ガス", "reading": "ていおんえきかガス", "meaning": "khí hóa lỏng ở nhiệt độ thấp"}, {"term": "保護手袋", "reading": "ほごてぶくろ", "meaning": "găng bảo hộ"}, {"term": "着用", "reading": "ちゃくよう", "meaning": "mang, mặc đồ bảo hộ"}, {"term": "皮膚", "reading": "ひふ", "meaning": "da"}, {"term": "Mẫu câu tiếng Nhật", "reading": "Cách đọc bằng kana", "meaning": "Nghĩa tiếng Việt / cách xử lý khi làm bài"}, {"term": "～は、～である。", "reading": "～は、～である。", "meaning": "“... là ...”. Kiểm tra toàn bộ định nghĩa và điều kiện."}, {"term": "～してはならない。", "reading": "～してはならない。", "meaning": "“Không được ...”. Đây là điều cấm, không phải lời khuyên."}, {"term": "～しなければならない。", "reading": "～しなければならない。", "meaning": "“Phải ...”. Kiểm tra hành động có thật sự bắt buộc không."}, {"term": "～してもよい。", "reading": "～してもよい。", "meaning": "“Có thể / được phép ...”. Chú ý điều kiện cho phép và an toàn."}, {"term": "～を用いると、～できる。", "reading": "～をもちいると、～できる。", "meaning": "“Dùng ... thì có thể ...”. Xét quan hệ nguyên nhân và kết quả."}, {"term": "～を加えると、～が生じる。", "reading": "～をくわえると、～がしょうじる。", "meaning": "“Thêm ... thì xuất hiện ...”. Kiểm tra lượng thuốc thử và hiện tượng."}, {"term": "～を過剰に加えると、～。", "reading": "～をかじょうにくわえると、～。", "meaning": "“Khi thêm dư ...”. Phân biệt với lượng ít; có thể tạo phức tan."}, {"term": "～よりも、～。", "reading": "～よりも、～。", "meaning": "“... hơn ...”. Không đảo chiều so sánh."}, {"term": "～の場合、～。", "reading": "～のばあい、～。", "meaning": "“Trong trường hợp ...”. Điều kiện giới hạn phạm vi kết luận."}, {"term": "一般に、～。", "reading": "いっぱんに、～。", "meaning": "“Nhìn chung ...”. Không tự biến thành quy luật tuyệt đối."}, {"term": "いずれも～。", "reading": "いずれも～。", "meaning": "“Tất cả đều ...”. Chỉ một trường hợp không đúng cũng bác bỏ phát biểu."}, {"term": "～以下／～以上", "reading": "～いか／～いじょう", "meaning": "“Không quá / ít nhất ...”. Cả hai đều gồm giá trị ở ranh giới."}, {"term": "～に比例する。", "reading": "～にひれいする。", "meaning": "“Tỉ lệ thuận với ...”. Phân biệt 反比例（はんぴれい）: tỉ lệ nghịch."}, {"term": "～とすれば、～。", "reading": "～とすれば、～。", "meaning": "“Nếu đặt / giả sử ...”. Giữ nguyên tên biến, đơn vị và giả thiết."}, {"term": "～に留意すれば、～。", "reading": "～にりゅういすれば、～。", "meaning": "“Nếu chú ý đến ...”. Trong phép tính, xét chữ số có nghĩa trước khi làm tròn."}, {"term": "～が共存する／共存下", "reading": "～がきょうぞんする／きょうぞんか", "meaning": "“Có mặt đồng thời / trong sự hiện diện của ...”. Xét môi trường phản ứng."}, {"term": "～のもとで、～。", "reading": "～のもとで、～。", "meaning": "“Trong điều kiện ...”. Kiểm tra nhiệt độ, áp suất và lượng chất được giữ cố định."}, {"term": "～とは、～をいう。", "reading": "～とは、～をいう。", "meaning": "“... được định nghĩa là ...”. So sánh đúng khái niệm, không chỉ từ khóa."}]'::jsonb, 60);
